INSERT INTO manna_words (word, scripture_reference, scripture_text, created_at) VALUES
  ('GRACE', 'Ephesians 2:8', 'For it is by grace you have been saved, through faith — and this is not from yourselves, it is the gift of God.', NOW()),
  ('FAITH', 'Hebrews 11:1', 'Now faith is confidence in what we hope for and assurance about what we do not see.', NOW()),
  ('PEACE', 'John 14:27', 'Peace I leave with you; my peace I give you. I do not give to you as the world gives. Do not let your hearts be troubled and do not be afraid.', NOW()),
  ('ABIDE', 'John 15:4', 'Abide in me, and I in you. As the branch cannot bear fruit by itself, unless it abides in the vine, neither can you, unless you abide in me.', NOW()),
  ('ARISE', 'Isaiah 60:1', 'Arise, shine, for your light has come, and the glory of the LORD rises upon you.', NOW()),
  ('BLESS', 'Numbers 6:24', 'The LORD bless you and keep you.', NOW()),
  ('BREAD', 'John 6:35', 'Then Jesus declared, I am the bread of life. Whoever comes to me will never go hungry, and whoever believes in me will never be thirsty.', NOW()),
  ('CROSS', 'Galatians 6:14', 'May I never boast except in the cross of our Lord Jesus Christ, through which the world has been crucified to me, and I to the world.', NOW()),
  ('CROWN', 'Revelation 2:10', 'Be faithful, even to the point of death, and I will give you life as your victor''s crown.', NOW()),
  ('DWELL', 'Psalm 23:6', 'Surely goodness and love will follow me all the days of my life, and I will dwell in the house of the LORD forever.', NOW()),
  ('EARTH', 'Psalm 24:1', 'The earth is the LORD''s, and everything in it, the world, and all who live in it.', NOW()),
  ('EGYPT', 'Exodus 20:2', 'I am the LORD your God, who brought you out of Egypt, out of the land of slavery.', NOW()),
  ('EXILE', 'Jeremiah 29:7', 'Also, seek the peace and prosperity of the city to which I have carried you into exile. Pray to the LORD for it.', NOW()),
  ('FLESH', 'John 1:14', 'The Word became flesh and made his dwelling among us. We have seen his glory, the glory of the one and only Son, who came from the Father, full of grace and truth.', NOW()),
  ('FLOOD', 'Genesis 9:11', 'I establish my covenant with you: Never again will all life be destroyed by the waters of a flood; never again will there be a flood to destroy the earth.', NOW()),
  ('GLORY', 'Romans 8:18', 'I consider that our present sufferings are not worth comparing with the glory that will be revealed in us.', NOW()),
  ('HEART', 'Proverbs 4:23', 'Above all else, guard your heart, for everything you do flows from it.', NOW()),
  ('JUDAH', 'Genesis 49:10', 'The scepter will not depart from Judah, nor the ruler''s staff from between his feet, until he to whom it belongs shall come.', NOW()),
  ('JUDAS', 'Matthew 26:25', 'Then Judas, the one who would betray him, said, Surely you don''t mean me, Rabbi? Jesus answered, You have said so.', NOW()),
  ('LAMBS', 'Isaiah 40:11', 'He tends his flock like a shepherd: He gathers the lambs in his arms and carries them close to his heart.', NOW()),
  ('LIGHT', 'John 8:12', 'When Jesus spoke again to the people, he said, I am the light of the world. Whoever follows me will never walk in darkness, but will have the light of life.', NOW()),
  ('LIONS', 'Daniel 6:22', 'My God sent his angel, and he shut the mouths of the lions. They have not hurt me, because I was found innocent in his sight.', NOW()),
  ('MOSES', 'Deuteronomy 34:10', 'Since then, no prophet has risen in Israel like Moses, whom the LORD knew face to face.', NOW()),
  ('MYRRH', 'Matthew 2:11', 'On coming to the house, they saw the child with his mother Mary, and they bowed down and worshiped him. Then they opened their treasures and presented him with gifts of gold, frankincense and myrrh.', NOW()),
  ('OMEGA', 'Revelation 22:13', 'I am the Alpha and the Omega, the First and the Last, the Beginning and the End.', NOW()),
  ('PETER', 'Matthew 16:18', 'And I tell you that you are Peter, and on this rock I will build my church, and the gates of Hades will not overcome it.', NOW()),
  ('PLEAD', 'Job 9:15', 'Though I were innocent, I could not answer him; I could only plead with my Judge for mercy.', NOW()),
  ('REIGN', 'Revelation 11:15', 'The kingdom of the world has become the kingdom of our Lord and of his Messiah, and he will reign for ever and ever.', NOW()),
  ('RISEN', 'Matthew 28:6', 'He is not here; he has risen, just as he said. Come and see the place where he lay.', NOW()),
  ('RIVER', 'Revelation 22:1', 'Then the angel showed me the river of the water of life, as clear as crystal, flowing from the throne of God and of the Lamb.', NOW()),
  ('SATAN', 'Job 1:7', 'The LORD said to Satan, Where have you come from? Satan answered the LORD, From roaming throughout the earth, going back and forth on it.', NOW()),
  ('SEEKS', 'Matthew 7:8', 'For everyone who asks receives; the one who seeks finds; and to the one who knocks, the door will be opened.', NOW()),
  ('SERVE', 'Joshua 24:15', 'But as for me and my household, we will serve the LORD.', NOW()),
  ('SHEEP', 'John 10:14', 'I am the good shepherd; I know my sheep and my sheep know me.', NOW()),
  ('SINAI', 'Exodus 19:20', 'The LORD descended to the top of Mount Sinai and called Moses to the top of the mountain. So Moses went up.', NOW()),
  ('SMITE', 'Psalm 121:6', 'The sun will not smite you by day, nor the moon by night.', NOW()),
  ('STAFF', 'Psalm 23:4', 'Even though I walk through the darkest valley, I will fear no evil, for you are with me; your rod and your staff, they comfort me.', NOW()),
  ('STONE', 'Psalm 118:22', 'The stone the builders rejected has become the cornerstone.', NOW()),
  ('SWORD', 'Ephesians 6:17', 'Take the helmet of salvation and the sword of the Spirit, which is the word of God.', NOW()),
  ('TABLE', 'Psalm 23:5', 'You prepare a table before me in the presence of my enemies. You anoint my head with oil; my cup overflows.', NOW()),
  ('TEACH', 'Psalm 25:4', 'Show me your ways, LORD, teach me your paths.', NOW()),
  ('TITHE', 'Malachi 3:10', 'Bring the whole tithe into the storehouse, that there may be food in my house. Test me in this, says the LORD Almighty.', NOW()),
  ('TOWER', 'Proverbs 18:10', 'The name of the LORD is a fortified tower; the righteous run to it and are safe.', NOW()),
  ('TRUST', 'Proverbs 3:5', 'Trust in the LORD with all your heart and lean not on your own understanding.', NOW()),
  ('TRUTH', 'John 8:32', 'Then you will know the truth, and the truth will set you free.', NOW()),
  ('WATCH', 'Mark 13:37', 'What I say to you, I say to everyone: Watch!', NOW()),
  ('WATER', 'John 4:14', 'But whoever drinks the water I give them will never thirst. Indeed, the water I give them will become in them a spring of water welling up to eternal life.', NOW()),
  ('WHEAT', 'Matthew 13:30', 'Let both grow together until the harvest. At that time I will tell the harvesters: First collect the weeds and tie them in bundles to be burned; then gather the wheat and bring it into my barn.', NOW()),
  ('WRATH', 'Romans 5:9', 'Since we have now been justified by his blood, how much more shall we be saved from God''s wrath through him!', NOW()),
  ('SHOUT', 'Psalm 100:1', 'Shout for joy to the LORD, all the earth.', NOW()),
  ('ABOVE', 'Colossians 3:2', 'Set your minds on things above, not on earthly things.', NOW()),
  ('AGAIN', 'John 3:3', 'Jesus replied, Very truly I tell you, no one can see the kingdom of God unless they are born again.', NOW()),
  ('ANGER', 'Ephesians 4:26', 'In your anger do not sin: Do not let the sun go down while you are still angry.', NOW()),
  ('ARMOR', 'Ephesians 6:11', 'Put on the full armor of God, so that you can take your stand against the devil''s schemes.', NOW()),
  ('BEGAT', 'Matthew 1:16', 'And Jacob begat Joseph the husband of Mary, of whom was born Jesus, who is called Christ.', NOW()),
  ('BEING', 'Acts 17:28', 'For in him we live and move and have our being. As some of your own poets have said, We are his offspring.', NOW()),
  ('BLOOD', 'Hebrews 9:22', 'Without the shedding of blood there is no forgiveness.', NOW()),
  ('BONES', 'Ezekiel 37:3', 'He asked me, Son of man, can these bones live? I said, Sovereign LORD, you alone know.', NOW()),
  ('BOUND', 'Matthew 18:18', 'Truly I tell you, whatever you bind on earth will be bound in heaven, and whatever you loose on earth will be loosed in heaven.', NOW()),
  ('CALEB', 'Numbers 14:24', 'But because my servant Caleb has a different spirit and follows me wholeheartedly, I will bring him into the land he went to, and his descendants will inherit it.', NOW()),
  ('CHILD', 'Isaiah 9:6', 'For to us a child is born, to us a son is given; and the government shall be upon his shoulder.', NOW()),
  ('CHOSE', 'John 15:16', 'You did not choose me, but I chose you and appointed you so that you might go and bear fruit.', NOW()),
  ('CLEAN', 'Psalm 51:10', 'Create in me a clean heart, O God, and renew a right spirit within me.', NOW()),
  ('CLOUD', 'Exodus 13:21', 'By day the LORD went ahead of them in a pillar of cloud to guide them on their way and by night in a pillar of fire to give them light.', NOW()),
  ('COMES', 'Psalm 121:2', 'My help comes from the LORD, the Maker of heaven and earth.', NOW()),
  ('DAILY', 'Matthew 6:11', 'Give us today our daily bread.', NOW()),
  ('DEATH', 'Romans 6:23', 'For the wages of sin is death, but the gift of God is eternal life in Christ Jesus our Lord.', NOW()),
  ('DOUBT', 'Matthew 14:31', 'Immediately Jesus reached out his hand and caught him. You of little faith, he said, why did you doubt?', NOW()),
  ('DRINK', 'John 7:37', 'On the last and greatest day of the festival, Jesus stood and said in a loud voice, Let anyone who is thirsty come to me and drink.', NOW()),
  ('DROVE', 'John 2:15', 'So he made a whip out of cords, and drove all from the temple courts, both sheep and cattle.', NOW()),
  ('ENTER', 'Matthew 7:13', 'Enter through the narrow gate. For wide is the gate and broad is the road that leads to destruction, and many enter through it.', NOW()),
  ('SNARE', 'Psalm 91:3', 'Surely he will save you from the fowler''s snare and from the deadly pestilence.', NOW()),
  ('FEAST', 'Isaiah 25:6', 'On this mountain the LORD Almighty will prepare a feast of rich food for all peoples.', NOW()),
  ('FIGHT', '1 Timothy 6:12', 'Fight the good fight of the faith. Take hold of the eternal life to which you were called.', NOW()),
  ('FINDS', 'Proverbs 18:22', 'He who finds a wife finds what is good and receives favor from the LORD.', NOW()),
  ('FIRST', 'Matthew 6:33', 'But seek first his kingdom and his righteousness, and all these things will be given to you as well.', NOW()),
  ('FLAME', 'Hebrews 1:7', 'He makes his angels winds, and his ministers a flame of fire.', NOW()),
  ('FLOCK', 'Psalm 77:20', 'You led your people like a flock by the hand of Moses and Aaron.', NOW()),
  ('FOUND', 'Luke 15:24', 'For this son of mine was dead and is alive again; he was lost and is found. So they began to celebrate.', NOW()),
  ('FREED', 'Romans 8:2', 'Because through Christ Jesus the law of the Spirit who gives life has freed you from the law of sin and death.', NOW()),
  ('FRUIT', 'Galatians 5:22', 'But the fruit of the Spirit is love, joy, peace, forbearance, kindness, goodness, faithfulness.', NOW()),
  ('GATES', 'Psalm 100:4', 'Enter his gates with thanksgiving and his courts with praise; give thanks to him and praise his name.', NOW()),
  ('GIVES', 'James 1:5', 'If any of you lacks wisdom, you should ask God, who gives generously to all without finding fault.', NOW()),
  ('GOING', 'John 14:2', 'My Father''s house has many rooms; if that were not so, would I have told you that I am going there to prepare a place for you?', NOW()),
  ('GRAIN', 'Psalm 72:16', 'May grain abound throughout the land; on the tops of the hills may it sway. May the crops flourish like Lebanon and thrive like the grass of the field.', NOW()),
  ('GRAVE', 'Hosea 13:14', 'I will deliver this people from the power of the grave; I will redeem them from death.', NOW()),
  ('GREAT', 'Deuteronomy 7:21', 'Do not be terrified by them, for the LORD your God, who is among you, is a great and awesome God.', NOW()),
  ('GUARD', 'Philippians 4:7', 'And the peace of God, which transcends all understanding, will guard your hearts and your minds in Christ Jesus.', NOW()),
  ('HANDS', 'Psalm 24:4', 'The one who has clean hands and a pure heart, who does not trust in an idol or swear by a false name.', NOW()),
  ('HEALS', 'Psalm 147:3', 'He heals the brokenhearted and binds up their wounds.', NOW()),
  ('HEARS', 'Psalm 34:17', 'The righteous cry out, and the LORD hears them; he delivers them from all their troubles.', NOW()),
  ('HELPS', 'Romans 8:26', 'The Spirit helps us in our weakness. We do not know what we ought to pray for, but the Spirit himself intercedes for us.', NOW()),
  ('HOMER', 'Leviticus 27:16', 'If a man dedicates to the LORD part of his family land, its value is to be set according to the amount of seed required for it — fifty shekels of silver to a homer of barley seed.', NOW()),
  ('HONOR', 'Proverbs 3:9', 'Honor the LORD with your wealth, with the firstfruits of all your crops.', NOW()),
  ('HEIRS', 'Romans 8:17', 'Now if we are children, then we are heirs — heirs of God and co-heirs with Christ, if indeed we share in his sufferings in order that we may also share in his glory.', NOW()),
  ('HOUSE', 'Psalm 127:1', 'Unless the LORD builds the house, the builders labor in vain.', NOW()),
  ('HYMNS', 'Colossians 3:16', 'Let the message of Christ dwell among you richly as you teach and admonish one another with all wisdom through psalms, hymns, and songs from the Spirit.', NOW()),
  ('IMAGE', 'Genesis 1:27', 'So God created mankind in his own image, in the image of God he created them.', NOW()),
  ('ISAAC', 'Genesis 22:2', 'Then God said, Take your son, your only son, whom you love — Isaac — and go to the region of Moriah.', NOW()),
  ('JACOB', 'Genesis 32:28', 'Then the man said, Your name will no longer be Jacob, but Israel, because you have struggled with God and with humans and have overcome.', NOW()),
  ('JONAH', 'Jonah 2:1', 'From inside the fish Jonah prayed to the LORD his God.', NOW()),
  ('JUDGE', 'Romans 14:10', 'You, then, why do you judge your brother or sister? Or why do you treat them with contempt? For we will all stand before God''s judgment seat.', NOW()),
  ('KEEPS', 'Proverbs 19:16', 'Whoever keeps commandments keeps their life, but whoever shows contempt for their ways will die.', NOW()),
  ('KNEEL', 'Psalm 95:6', 'Come, let us bow down in worship, let us kneel before the LORD our Maker.', NOW()),
  ('KNOWN', 'Galatians 4:9', 'But now that you know God — or rather are known by God — how is it that you are turning back to those weak and miserable forces?', NOW()),
  ('LAMPS', 'Matthew 25:4', 'The wise ones, however, took oil in jars along with their lamps.', NOW()),
  ('LEADS', 'Psalm 23:2', 'He makes me lie down in green pastures, he leads me beside quiet waters.', NOW()),
  ('LEARN', 'Matthew 11:29', 'Take my yoke upon you and learn from me, for I am gentle and humble in heart, and you will find rest for your souls.', NOW()),
  ('LIVES', 'Galatians 2:20', 'I have been crucified with Christ and I no longer live, but Christ lives in me.', NOW()),
  ('SPARE', 'Romans 8:32', 'He who did not spare his own Son, but gave him up for us all — how will he not also, along with him, graciously give us all things?', NOW()),
  ('LOWLY', 'Matthew 11:29', 'For I am gentle and lowly in heart, and you will find rest for your souls.', NOW()),
  ('MARKS', 'Galatians 6:17', 'From now on, let no one cause me trouble, for I bear on my body the marks of Jesus.', NOW()),
  ('ABRAM', 'Genesis 12:1', 'The LORD had said to Abram, Go from your country, your people and your father''s household to the land I will show you.', NOW()),
  ('MIGHT', 'Zechariah 4:6', 'Not by might nor by power, but by my Spirit, says the LORD Almighty.', NOW()),
  ('MOREH', 'Genesis 12:6', 'Abram traveled through the land as far as the site of the great tree of Moreh at Shechem.', NOW()),
  ('NEEDS', 'Philippians 4:19', 'And my God will meet all your needs according to the riches of his glory in Christ Jesus.', NOW()),
  ('NIGHT', 'Psalm 91:5', 'You will not fear the terror of night, nor the arrow that flies by day.', NOW()),
  ('NOBLE', 'Proverbs 31:10', 'A wife of noble character who can find? She is worth far more than rubies.', NOW()),
  ('OFFER', 'Romans 12:1', 'Therefore, I urge you, brothers and sisters, in view of God''s mercy, to offer your bodies as a living sacrifice, holy and pleasing to God.', NOW()),
  ('OLIVE', 'Romans 11:17', 'If some of the branches have been broken off, and you, though a wild olive shoot, have been grafted in among the others and now share in the nourishing sap from the olive root.', NOW()),
  ('PAINS', 'Romans 8:22', 'We know that the whole creation has been groaning as in the pains of childbirth right up to the present time.', NOW()),
  ('PATHS', 'Psalm 23:3', 'He guides me along the right paths for his name''s sake.', NOW()),
  ('PRESS', 'Philippians 3:14', 'I press on toward the goal to win the prize for which God has called me heavenward in Christ Jesus.', NOW()),
  ('PLUMB', 'Amos 7:8', 'And the LORD asked me, What do you see, Amos? A plumb line, I replied. Then the Lord said, Look, I am setting a plumb line among my people Israel.', NOW()),
  ('POWER', 'Acts 1:8', 'But you will receive power when the Holy Spirit comes on you; and you will be my witnesses in Jerusalem, and in all Judea and Samaria, and to the ends of the earth.', NOW()),
  ('PRICE', '1 Corinthians 6:20', 'You were bought at a price. Therefore honor God with your bodies.', NOW()),
  ('PRIDE', 'Proverbs 11:2', 'When pride comes, then comes disgrace, but with humility comes wisdom.', NOW()),
  ('PROUD', 'James 4:6', 'But he gives us more grace. That is why Scripture says: God opposes the proud but shows favor to the humble.', NOW()),
  ('RAISE', 'John 6:40', 'For my Father''s will is that everyone who looks to the Son and believes in him shall have eternal life, and I will raise them up at the last day.', NOW()),
  ('READS', 'Revelation 1:3', 'Blessed is the one who reads aloud the words of this prophecy.', NOW()),
  ('READY', 'Matthew 24:44', 'So you also must be ready, because the Son of Man will come at an hour when you do not expect him.', NOW()),
  ('REAPS', 'Galatians 6:7', 'Do not be deceived: God cannot be mocked. A man reaps what he sows.', NOW()),
  ('SCORN', 'Psalm 44:13', 'You have made us the scorn of our neighbors, the derision and mockery of those around us.', NOW()),
  ('REPAY', 'Romans 12:19', 'Do not take revenge, my dear friends, but leave room for God''s wrath, for it is written: It is mine to avenge; I will repay, says the LORD.', NOW()),
  ('RENEW', 'Isaiah 40:31', 'But those who hope in the LORD will renew their strength. They will soar on wings like eagles.', NOW()),
  ('GIFTS', 'Romans 11:29', 'For God''s gifts and his call are irrevocable.', NOW()),
  ('RIGHT', 'Psalm 19:8', 'The precepts of the LORD are right, giving joy to the heart.', NOW()),
  ('ROYAL', '1 Peter 2:9', 'But you are a chosen people, a royal priesthood, a holy nation, God''s special possession.', NOW()),
  ('RULES', 'Psalm 103:19', 'The LORD has established his throne in heaven, and his kingdom rules over all.', NOW()),
  ('SAVED', 'Ephesians 2:8', 'For it is by grace you have been saved, through faith — and this is not from yourselves, it is the gift of God.', NOW()),
  ('SHINE', 'Matthew 5:16', 'In the same way, let your light shine before others, that they may see your good deeds and glorify your Father in heaven.', NOW()),
  ('SIGNS', 'John 20:30', 'Jesus performed many other signs in the presence of his disciples, which are not recorded in this book.', NOW()),
  ('SLEEP', 'Psalm 4:8', 'In peace I will lie down and sleep, for you alone, LORD, make me dwell in safety.', NOW()),
  ('SMALL', 'Zechariah 4:10', 'Who dares despise the day of small things?', NOW()),
  ('SOLID', 'Hebrews 5:14', 'But solid food is for the mature, who by constant use have trained themselves to distinguish good from evil.', NOW()),
  ('SONGS', 'Ephesians 5:19', 'Speaking to one another with psalms, hymns, and songs from the Spirit. Sing and make music from your heart to the Lord.', NOW()),
  ('SPEAK', 'Numbers 22:38', 'I must speak only what God puts in my mouth.', NOW()),
  ('SPEND', 'Isaiah 55:2', 'Why spend money on what is not bread, and your labor on what does not satisfy?', NOW()),
  ('STORE', 'Matthew 6:20', 'But store up for yourselves treasures in heaven, where moths and vermin do not destroy, and where thieves do not break in and steal.', NOW()),
  ('STRAP', 'Luke 3:16', 'I am not worthy to untie the strap of his sandals.', NOW()),
  ('SWEAR', 'Matthew 5:34', 'But I tell you, do not swear an oath at all: either by heaven, for it is God''s throne.', NOW()),
  ('SWEAT', 'Luke 22:44', 'And being in anguish, he prayed more earnestly, and his sweat was like drops of blood falling to the ground.', NOW()),
  ('TAKEN', 'Isaiah 53:8', 'By oppression and judgment he was taken away. Yet who of his generation protested?', NOW()),
  ('TEARS', 'Psalm 56:8', 'You have kept count of my tossings; put my tears in your bottle.', NOW()),
  ('THREE', 'Matthew 18:20', 'For where two or three gather in my name, there am I with them.', NOW()),
  ('TOUCH', 'Mark 5:28', 'Because she thought, If I just touch his clothes, I will be healed.', NOW()),
  ('TOWNS', 'Luke 4:43', 'But he said, I must proclaim the good news of the kingdom of God to the other towns also, because that is why I was sent.', NOW()),
  ('TRIBE', 'Revelation 5:5', 'See, the Lion of the tribe of Judah, the Root of David, has triumphed.', NOW()),
  ('UNITY', 'Psalm 133:1', 'How good and pleasant it is when God''s people live together in unity!', NOW()),
  ('UNTIL', 'Philippians 1:6', 'Being confident of this, that he who began a good work in you will carry it on to completion until the day of Christ Jesus.', NOW()),
  ('VOICE', 'John 10:27', 'My sheep listen to my voice; I know them, and they follow me.', NOW()),
  ('WANTS', '1 Timothy 2:4', 'Who wants all people to be saved and to come to a knowledge of the truth.', NOW()),
  ('WEARY', 'Isaiah 40:31', 'But those who hope in the LORD will renew their strength. They will soar on wings like eagles; they will run and not grow weary, they will walk and not be faint.', NOW()),
  ('WELLS', 'Isaiah 12:3', 'With joy you will draw water from the wells of salvation.', NOW()),
  ('WINDS', 'Psalm 104:4', 'He makes winds his messengers, flames of fire his servants.', NOW()),
  ('WINGS', 'Psalm 91:4', 'He will cover you with his feathers, and under his wings you will find refuge; his faithfulness will be your shield and rampart.', NOW()),
  ('WISER', 'Proverbs 9:9', 'Instruct the wise and they will be wiser still; teach the righteous and they will add to their learning.', NOW()),
  ('WOMEN', 'Luke 8:3', 'And Joanna the wife of Chuza, the manager of Herod''s household; Susanna; and many others. These women were helping to support them out of their own means.', NOW()),
  ('WORDS', 'Psalm 19:14', 'May these words of my mouth and this meditation of my heart be pleasing in your sight, LORD, my Rock and my Redeemer.', NOW()),
  ('WORKS', 'Ephesians 2:10', 'For we are God''s handiwork, created in Christ Jesus to do good works, which God prepared in advance for us to do.', NOW()),
  ('WORLD', 'John 3:16', 'For God so loved the world that he gave his one and only Son.', NOW()),
  ('WORRY', 'Matthew 6:34', 'Therefore do not worry about tomorrow, for tomorrow will worry about itself. Each day has enough trouble of its own.', NOW()),
  ('WORTH', 'Romans 8:18', 'I consider that our present sufferings are not worth comparing with the glory that will be revealed in us.', NOW()),
  ('WRITE', 'Habakkuk 2:2', 'Then the LORD replied: Write down the revelation and make it plain on tablets so that a herald may run with it.', NOW()),
  ('YOUNG', 'Psalm 119:9', 'How can a young person stay on the path of purity? By living according to your word.', NOW()),
  ('SOBER', '1 Thessalonians 5:6', 'So then, let us not be like others, who are asleep, but let us be awake and sober.', NOW()),
  ('AARON', 'Exodus 4:14', 'Then the LORD''s anger burned against Moses and he said, What about your brother, Aaron the Levite? I know he can speak well.', NOW()),
  ('ABNER', '2 Samuel 2:8', 'Meanwhile, Abner son of Ner, the commander of Saul''s army, had taken Ish-Bosheth son of Saul and brought him over to Mahanaim.', NOW()),
  ('ACHAN', 'Joshua 7:20', 'Achan replied, It is true! I have sinned against the LORD, the God of Israel. This is what I have done.', NOW()),
  ('ANNAS', 'Luke 3:2', 'During the high-priesthood of Annas and Caiaphas, the word of God came to John son of Zechariah in the wilderness.', NOW()),
  ('ASHER', 'Deuteronomy 33:24', 'About Asher he said: ''Most blessed of sons is Asher; let him be favored by his brothers, and let him bathe his feet in oil.''', NOW()),
  ('CYRUS', 'Isaiah 45:1', 'This is what the LORD says to his anointed, to Cyrus, whose right hand I take hold of to subdue nations before him.', NOW()),
  ('DAGON', '1 Samuel 5:4', 'But the following morning when they rose, there was Dagon, fallen on his face on the ground before the ark of the LORD!', NOW()),
  ('ELIAM', '2 Samuel 23:34', 'Eliphelet son of Ahasbai the Maakathite, Eliam son of Ahithophel the Gilonite.', NOW()),
  ('ENOCH', 'Genesis 5:24', 'Enoch walked faithfully with God; then he was no more, because God took him away.', NOW()),
  ('ETHAN', 'Psalm 89:1', 'A maskil of Ethan the Ezrahite. I will sing of the LORD''s great love forever; with my mouth I will make your faithfulness known through all generations.', NOW()),
  ('FELIX', 'Acts 24:24', 'Several days later Felix came with his wife Drusilla. He sent for Paul and listened to him as he spoke about faith in Christ Jesus.', NOW()),
  ('HAGAR', 'Genesis 21:17', 'God heard the boy crying, and the angel of God called to Hagar from heaven and said to her, What is the matter, Hagar? Do not be afraid.', NOW()),
  ('HEROD', 'Matthew 2:16', 'When Herod realized that he had been outwitted by the Magi, he was furious, and he gave orders to kill all the boys in Bethlehem.', NOW()),
  ('HIRAM', '1 Kings 5:12', 'The LORD gave Solomon wisdom, just as he had promised him. There were peaceful relations between Hiram and Solomon, and the two of them made a treaty.', NOW()),
  ('JABAL', 'Genesis 4:20', 'Adah gave birth to Jabal; he was the father of those who live in tents and raise livestock.', NOW()),
  ('JASON', 'Acts 17:6', 'But when they did not find them, they dragged Jason and some other believers before the city officials, shouting: These men who have caused trouble all over the world have now come here.', NOW()),
  ('JOASH', '2 Kings 12:2', 'Joash did what was right in the eyes of the LORD all the years Jehoiada the priest instructed him.', NOW()),
  ('JUBAL', 'Genesis 4:21', 'His brother''s name was Jubal; he was the father of all who play stringed instruments and pipes.', NOW()),
  ('LABAN', 'Genesis 29:10', 'When Jacob saw Rachel daughter of his uncle Laban, and Laban''s sheep, he went over and rolled the stone away from the mouth of the well.', NOW()),
  ('LYDIA', 'Acts 16:14', 'One of those listening was a woman from the city of Thyatira named Lydia, a dealer in purple cloth. The Lord opened her heart to respond to Paul''s message.', NOW()),
  ('MAMRE', 'Genesis 18:1', 'The LORD appeared to Abraham near the great trees of Mamre while he was sitting at the entrance to his tent in the heat of the day.', NOW()),
  ('MERAB', '1 Samuel 14:49', 'Saul''s sons were Jonathan, Ishvi and Malki-Shua. The name of his older daughter was Merab, and that of the younger was Michal.', NOW()),
  ('MESHA', '2 Kings 3:4', 'Now Mesha king of Moab raised sheep, and he had to pay the king of Israel a tribute of a hundred thousand lambs.', NOW()),
  ('NABAL', '1 Samuel 25:3', 'His name was Nabal and his wife''s name was Abigail. She was an intelligent and beautiful woman, but her husband was surly and mean in his dealings.', NOW()),
  ('PALTI', 'Numbers 13:9', 'From the tribe of Benjamin, Palti son of Raphu.', NOW()),
  ('PEREZ', 'Genesis 38:29', 'But when he drew back his hand, his brother came out, and she said, So this is how you have broken out! And he was named Perez.', NOW()),
  ('RAHAB', 'Hebrews 11:31', 'By faith the prostitute Rahab, because she welcomed the spies, was not killed with those who were disobedient.', NOW()),
  ('REUEL', 'Exodus 2:18', 'When the girls returned to Reuel their father, he asked them, Why have you returned so early today?', NOW()),
